use vstd::prelude::*;

verus! {
    fn get_first_elements(lst: Vec<Vec<i32>>) -> (result: Vec<i32>)
        requires
            lst.len() > 0, // Ensure that the outer array is not empty
            forall(|i: nat| i < lst.len() ==> lst[i].len() > 0), // Each inner array must be non-empty
        ensures
            result.len() == lst.len(), // Output length must match input length
            forall(|i: nat| i < lst.len() ==> result[i] == lst[i][0]), // Output must contain first elements
    {
        let mut result: Vec<i32> = Vec::new();
        let mut i: usize = 0;

        while i < lst.len()
            invariant
                i <= lst.len(), // i must not exceed the length of lst
                result.len() == i, // The length of result must equal i
                forall(|j: nat| j < i ==> result[j] == lst[j][0]), // All previous elements in result are correct
            decreases lst.len() - i,
        {
            result.push(lst[i][0]); // Push the first element of the i-th inner array
            i = i + 1; // Increment the index
        }

        result // Return the result vector
    }
}
